import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const n = Number(lines[0]);
const graph: number[][] = Array.from({ length: n + 1 }, () => []);
for (let i = 1; i < n; i++) {
  const [u, v] = lines[i].split(" ").map(Number);
  graph[u].push(v);
  graph[v].push(u);
}

// start から各頂点への距離を BFS で求める
function bfs(start: number): Int32Array {
  const dist = new Int32Array(n + 1).fill(-1);
  dist[start] = 0;
  const queue = [start];
  for (let head = 0; head < queue.length; head++) {
    const v = queue[head];
    for (const next of graph[v]) {
      if (dist[next] !== -1) continue;
      dist[next] = dist[v] + 1;
      queue.push(next);
    }
  }
  return dist;
}

// 1 から最も遠い頂点 far を求め、far から最も遠い距離が直径
const d1 = bfs(1);
let far = 1;
for (let v = 1; v <= n; v++) if (d1[v] > d1[far]) far = v;
const d2 = bfs(far);
let diameter = 0;
for (let v = 1; v <= n; v++) diameter = Math.max(diameter, d2[v]);
console.log(diameter);
